#include "cccacd10255ccf90_area_insert.hpp"
namespace recovered_area_insert{U add(U area,U id,U fresh,U scratch,Ports&p){U objects=p.objects();if((p.lookup(objects,id,scratch)&255)!=(p.success()&255))return 0;U count=p.read(area+0x194),list=area+0x190,duplicates=0;if(static_cast<int>(count)>0){U array=p.read(list);do{if(p.read(array)==id)++duplicates;array+=4;}while(--count);}if(duplicates)p.remove(area,id);U x=p.read(p.read(scratch)+0x90);p.write(scratch+8,x);if(p.index(area,scratch+8,x)){p.insert(list,id,p.read(scratch+8));}else{U capacity=p.read(list+8);if(p.read(list+4)==capacity)p.grow(list,capacity?capacity*2:16);U used=p.read(list+4),array=p.read(list);p.write(array+used*4,id);p.write(list+4,p.read(list+4)+1);}if((p.lookup(objects,id,scratch+4)&255)==(p.success()&255)){U object=p.read(scratch+4);if(object&&p.creature(object)){if(p.player(id))p.increment(area);if(fresh==1){U allocation=p.allocate(0x34);U event=allocation?p.event(allocation):0;p.half(event,12);U mode=p.mode();p.event_int(event,0,mode);U kind=p.kind(),target=p.read(area+0x120),ai=p.ai();p.enqueue(ai,0,0,id,target,kind,event);}}}return 1;}}
